def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    rectangles = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            r0 = min(y for y,x in cells); r1 = max(y for y,x in cells)
            c0 = min(x for y,x in cells); c1 = max(x for y,x in cells)
            area = (r1-r0+1)*(c1-c0+1)
            if area >= 6 and r1 > r0 and c1 > c0 and len(cells)/area >= 0.60:
                rectangles.append((color,r0,r1,c0,c1))
    result = [[background]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in rectangles:
        for y in range(r0,r1+1):
            for x in range(c0,c1+1):
                result[y][x] = color
    return result
